#include <bits/stdc++.h>
using namespace std;

struct Orientation {
    vector<pair<int,int>> cells;
    int w, h;
    int r, f;
};

vector<Orientation> getOrientations(const vector<pair<int,int>>& cells) {
    vector<Orientation> res;
    set<vector<pair<int,int>>> seen;
    for (int f = 0; f <= 1; f++) {
        for (int r = 0; r < 4; r++) {
            vector<pair<int,int>> transformed;
            for (auto [x, y] : cells) {
                int tx = x, ty = y;
                if (f) tx = -tx;
                for (int rr = 0; rr < r; rr++) {
                    int nx = ty, ny = -tx;
                    tx = nx; ty = ny;
                }
                transformed.push_back({tx, ty});
            }
            int minx = INT_MAX, miny = INT_MAX;
            for (auto [x, y] : transformed) { minx = min(minx, x); miny = min(miny, y); }
            for (auto& [x, y] : transformed) { x -= minx; y -= miny; }
            sort(transformed.begin(), transformed.end());
            if (seen.insert(transformed).second) {
                int maxx = 0, maxy = 0;
                for (auto [x, y] : transformed) { maxx = max(maxx, x); maxy = max(maxy, y); }
                res.push_back({transformed, maxx + 1, maxy + 1, r, f});
            }
        }
    }
    return res;
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<int> ksz(n);
    vector<vector<pair<int,int>>> raw(n);
    int totalCells = 0;
    for (int i = 0; i < n; i++) {
        cin >> ksz[i];
        raw[i].resize(ksz[i]);
        for (int j = 0; j < ksz[i]; j++) cin >> raw[i][j].first >> raw[i][j].second;
        totalCells += ksz[i];
    }

    vector<vector<Orientation>> allOrients(n);
    for (int i = 0; i < n; i++) allOrients[i] = getOrientations(raw[i]);

    vector<int> order(n);
    iota(order.begin(), order.end(), 0);
    sort(order.begin(), order.end(), [&](int a, int b){
        return ksz[a] > ksz[b];
    });

    int bestArea = INT_MAX, bestW = 0, bestH = 0;
    vector<int> bestX(n), bestY(n), bestR(n), bestF(n);

    int sq = max(1, (int)ceil(sqrt((double)totalCells)));
    vector<int> widths;
    for (int w = max(1, sq - 30); w <= sq + 100; w++) widths.push_back(w);
    for (int w = sq + 110; w <= min(totalCells, sq * 4); w += 20) widths.push_back(w);

    auto t0 = chrono::steady_clock::now();

    for (int W : widths) {
        if (chrono::duration_cast<chrono::milliseconds>(chrono::steady_clock::now()-t0).count()>7000) break;
        int maxH = totalCells / W + n * 11 + 20;
        if ((long long)W * maxH > 30000000LL) continue;
        vector<bool> grid(W * maxH, false);
        vector<int> colH(W, 0);
        int curH = 0;
        vector<int> px(n), py(n), pr(n), pf(n);
        bool ok = true;
        for (int idx = 0; idx < n; idx++) {
            int i = order[idx];
            int bestScore = INT_MAX; int bx=-1,by=-1,boi=-1;
            for (int oi = 0; oi < (int)allOrients[i].size(); oi++) {
                auto& o = allOrients[i][oi];
                if (o.w > W) continue;
                for (int x = 0; x <= W - o.w; x++) {
                    int miny = 0;
                    for (auto [cx,cy] : o.cells) miny = max(miny, colH[x+cx]-cy);
                    for (int y = max(0,miny); y + o.h <= maxH; y++) {
                        bool fit = true;
                        for (auto [cx,cy] : o.cells) if (grid[(x+cx)*maxH+(y+cy)]) {fit=false;break;}
                        if (fit) {
                            int newH = max(curH, y + o.h);
                            int score = newH * 100000 + y * 100 + x;
                            if (score < bestScore) { bestScore=score; bx=x; by=y; boi=oi; }
                            break;
                        }
                    }
                }
            }
            if (boi < 0) { ok=false; break; }
            px[i]=bx; py[i]=by; pr[i]=allOrients[i][boi].r; pf[i]=allOrients[i][boi].f;
            for (auto [cx,cy] : allOrients[i][boi].cells) {
                grid[(bx+cx)*maxH+(by+cy)]=true;
                colH[bx+cx]=max(colH[bx+cx],by+cy+1);
                curH=max(curH,by+cy+1);
            }
        }
        if (!ok) continue;
        int area = W * curH;
        if (area < bestArea || (area==bestArea && curH < bestH)) {
            bestArea=area; bestW=W; bestH=curH;
            bestX=px; bestY=py; bestR=pr; bestF=pf;
        }
    }

    if (bestArea == INT_MAX) {
        int W = max(10, sq);
        bestW = W; bestH = totalCells + n * 10;
        int y = 0;
        for (int i = 0; i < n; i++) {
            bestX[i]=0; bestY[i]=y; bestR[i]=0; bestF[i]=0;
            y += 11;
        }
        bestH = y;
    }

    cout << bestW << " " << bestH << "\n";
    for (int i = 0; i < n; i++)
        cout << bestX[i] << " " << bestY[i] << " " << bestR[i] << " " << bestF[i] << "\n";
}
